-- Read-only cross-map automatic D discovery. Runtime installs the same index.
-- For a live production database, apply outside a transaction before restarting.
create index concurrently if not exists room_nodes_automatic_d_idx on room_nodes(room_key, uid)
  where deleted_at is null and (btrim(regexp_replace(regexp_replace(regexp_replace(btrim(regexp_replace(replace(replace(replace(replace(regexp_replace(coalesce(data->>'text', ''), '<[^>]+>', '', 'g'), '&nbsp;', ' '), '&amp;', '&'), chr(160), ' '), chr(12288), ' '), '[[:space:]]+', ' ', 'g')), '^[-*•●][[:space:]]*', ''), '^【[[:space:]]*', ''), '[[:space:]]*】$', '')) ~* '^d[[:space:]]*[：:][[:space:]]*[^[:space:]]' and strpos(btrim(regexp_replace(regexp_replace(regexp_replace(btrim(regexp_replace(replace(replace(replace(replace(regexp_replace(coalesce(data->>'text', ''), '<[^>]+>', '', 'g'), '&nbsp;', ' '), '&amp;', '&'), chr(160), ' '), chr(12288), ' '), '[[:space:]]+', ' ', 'g')), '^[-*•●][[:space:]]*', ''), '^【[[:space:]]*', ''), '[[:space:]]*】$', '')), '自动') > 0);
